    <Spotlight className="rounded-xl border p-12 text-center">
      <h2 className="text-2xl font-bold">Move your cursor</h2>
      <p className="mt-2 text-sm text-muted-foreground">
        The glow follows you.
      </p>
    </Spotlight>
  );
}

